// Perpustakaan English Quest: seluruh artikel ditanam di aplikasi agar bisa dibaca gratis tanpa internet.
const libraryCategories = ["Semua", "Grammar", "Kosakata", "Speaking", "Reading", "Writing"];
const libraryArticles = [
  {
    id:"sentence-order", category:"Grammar", icon:"🧱", level:"Pemula", minutes:6,
    title:"Rangka kalimat bahasa Inggris: siapa melakukan apa?",
    summary:"Kenali pola dasar Subject–Verb–Object, posisi keterangan, dan urutan kata yang paling sering dipakai.",
    goals:["Menemukan subjek dan kata kerja utama.","Menyusun kalimat sederhana dengan urutan yang wajar.","Membedakan kata sifat dan keterangan waktu/tempat."],
    sections:[
      {title:"1. Mulai dari inti kalimat: S + V", text:["Banyak kalimat bahasa Inggris punya inti Subject (S) + Verb (V). Subject adalah orang/benda yang dibicarakan; verb menyatakan tindakan atau keadaan. Dalam I study, I adalah subject dan study adalah verb. Bahasa Indonesia kadang mengizinkan urutan yang lebih lentur, tetapi bahasa Inggris biasanya membutuhkan subject yang jelas.","Kalimat perintah adalah pengecualian penting: subject you sering tidak ditulis, seperti Open the door! (Bukalah pintu!)."], examples:[{en:"The children laugh.",id:"Anak-anak tertawa.",note:"The children = subject; laugh = verb."},{en:"My sister is tired.",id:"Kakak/adik perempuan saya lelah.",note:"My sister = subject; is menghubungkan subjek dengan keadaan tired."}]},
      {title:"2. Tambahkan object dan pelengkap", text:["Kalau tindakan mengenai sesuatu atau seseorang, letakkan object setelah verb: Subject + Verb + Object. Jangan memindahkan object ke depan seperti yang kadang terdengar alami dalam bahasa Indonesia.","Kata kerja tertentu tidak membutuhkan object. She sleeps sudah lengkap; sleeps an early morning tidak benar. Be (am/is/are) biasanya diikuti nama, sifat, atau keterangan tempat—bukan object tindakan."], examples:[{en:"We watch a movie.",id:"Kami menonton film.",note:"We = S, watch = V, a movie = O."},{en:"Rina is a student.",id:"Rina seorang pelajar.",note:"is menghubungkan Rina dengan identitasnya."}]},
      {title:"3. Keterangan dan kata sifat", text:["Keterangan waktu atau tempat biasanya diletakkan setelah inti kalimat. Jika ada keduanya, urutan tempat lalu waktu sering terasa alami: at home every evening. Keterangan frekuensi seperti always biasanya muncul sebelum kata kerja tindakan, tetapi setelah be: I often read; I am often busy.","Dalam bahasa Inggris, kata sifat umumnya mendahului kata benda: a small book, bukan a book small. Artikel a/an/the tetap berada sebelum kata sifat."], examples:[{en:"They play football at school after lunch.",id:"Mereka bermain sepak bola di sekolah setelah makan siang.",note:"Urutan: S + V + O + tempat + waktu."},{en:"She has a beautiful red bag.",id:"Dia punya tas merah yang cantik.",note:"Kata sifat berada sebelum bag."}]}
    ],
    mistake:{wrong:"I very like this song.",right:"I really like this song.",why:"Very biasanya menerangkan kata sifat/keterangan, bukan langsung kata kerja like. Really dapat menerangkan like."},
    keyPoints:["Susunan paling umum: Subject + Verb + Object.","Be menghubungkan subjek dengan identitas, sifat, atau tempat.","Kata sifat biasanya sebelum kata benda; keterangan memberi info tambahan."],
    check:{question:"Pilih kalimat dengan urutan kata yang benar.",options:["She reads a book every night.","Reads she every night a book.","She a book reads every night."],answer:0,explanation:"Pola yang paling wajar adalah subject She + verb reads + object a book + keterangan waktu."}
  },
  {
    id:"be-do", category:"Grammar", icon:"🔗", level:"Pemula", minutes:7,
    title:"Am, is, are, do, dan does: kapan dipakai?",
    summary:"Pahami perbedaan be-verb untuk keadaan/identitas dan do/does sebagai pembantu pertanyaan serta kalimat negatif.",
    goals:["Memilih am/is/are sesuai subject.","Membuat negatif dan pertanyaan dengan be.","Memakai do/does hanya saat diperlukan."],
    sections:[
      {title:"1. Am/is/are menghubungkan subject", text:["Gunakan am, is, atau are untuk menyatakan identitas, sifat, lokasi, umur, atau keadaan. Padankan: I am; he/she/it atau satu nama is; you/we/they atau jamak are. Dalam present, kalimat nominal bahasa Inggris memerlukan be; bahasa Indonesia sering tidak memakai kata penghubung, sehingga bagian ini mudah terlewat.","Be + kata kerja -ing juga membentuk present continuous, misalnya They are studying. Itu pola berbeda dari They are students."], examples:[{en:"I am ready.",id:"Saya siap.",note:"I selalu dipasangkan dengan am."},{en:"Naya and Bimo are at school.",id:"Naya dan Bimo berada di sekolah.",note:"Dua orang = subject jamak, jadi are."}]},
      {title:"2. Negatif dan pertanyaan dengan be", text:["Untuk negatif, letakkan not setelah be: is not/isn't, are not/aren't. Untuk pertanyaan ya/tidak, pindahkan be ke depan subject: Is she ready? Are they at home? Tidak perlu menambah do.","Jawaban pendek juga memakai be: Yes, she is. / No, they aren't. Jangan mengulang seluruh kalimat jika tidak diperlukan."], examples:[{en:"He isn't tired.",id:"Dia tidak lelah.",note:"not langsung setelah is."},{en:"Are you a student? Yes, I am.",id:"Apakah kamu pelajar? Ya.",note:"Be berpindah ke depan pada pertanyaan."}]},
      {title:"3. Do/does membantu kata kerja tindakan", text:["Pada present simple, do/does dipakai untuk pertanyaan dan negatif dengan kata kerja tindakan seperti like, play, work, atau study. Do cocok dengan I/you/we/they; does cocok dengan he/she/it. Setelah does, kata kerja kembali ke bentuk dasar: Does he work? He doesn't work.","Kalimat positif biasa tidak membutuhkan do: She works here. Do kadang dipakai dalam positif untuk penekanan, seperti I do understand, tetapi itu penggunaan khusus."], examples:[{en:"Do they speak English?",id:"Apakah mereka berbicara bahasa Inggris?",note:"They menggunakan do; speak tetap bentuk dasar."},{en:"Mira doesn't eat meat.",id:"Mira tidak makan daging.",note:"doesn't + eat, bukan eats."}]}
    ],
    mistake:{wrong:"Do you are happy? / She don't like tea.",right:"Are you happy? / She doesn't like tea.",why:"Be membuat pertanyaan sendiri. Untuk subject she, gunakan does/doesn't, lalu verb kembali ke bentuk dasar."},
    keyPoints:["Identitas/sifat/lokasi: be (am/is/are).","Pertanyaan/negatif dengan action verb: do/does + verb dasar.","Setelah does/doesn't, jangan tambahkan -s lagi pada verb."],
    check:{question:"Mana pertanyaan yang benar untuk menanyakan apakah Dika bekerja di sini?",options:["Does Dika work here?","Is Dika work here?","Do Dika works here?"],answer:0,explanation:"Dika = he, maka gunakan does, dan verb setelahnya tetap work."}
  },
  {
    id:"simple-present", category:"Grammar", icon:"🔁", level:"Pemula", minutes:7,
    title:"Simple Present: rutinitas, kebiasaan, dan fakta",
    summary:"Pelajari kapan memakai simple present, aturan -s/-es, kata keterangan frekuensi, dan bentuk tanya/negatif.",
    goals:["Menceritakan kebiasaan dan fakta umum.","Menambahkan akhiran yang tepat untuk he/she/it.","Membuat pertanyaan dengan do/does."],
    sections:[
      {title:"1. Kapan simple present digunakan?", text:["Gunakan simple present untuk kebiasaan, rutinitas, fakta yang dianggap benar secara umum, dan jadwal tetap. Tense ini tidak otomatis berarti tindakan terjadi tepat saat kita berbicara. Untuk tindakan yang sedang berlangsung sekarang, biasanya gunakan present continuous.","Kata petunjuk seperti every day, usually, often, sometimes, never, dan on Mondays sering muncul, tetapi keputusan tetap berdasarkan makna kalimat."], examples:[{en:"I walk to school every morning.",id:"Saya berjalan kaki ke sekolah setiap pagi.",note:"Rutinitas berulang."},{en:"Water boils at 100°C.",id:"Air mendidih pada suhu 100°C.",note:"Fakta umum."}]},
      {title:"2. Akhiran kata kerja untuk he/she/it", text:["Dengan I/you/we/they, pakai verb dasar: play, study, watch. Dengan he/she/it atau satu nama, biasanya tambahkan -s: plays, reads. Tambahkan -es pada banyak verb yang berakhir -s, -sh, -ch, -x, atau -o: watches, washes, goes. Konsonan + y berubah menjadi -ies: study → studies; tetapi play → plays karena sebelum y ada vokal.","Kata kerja be mengikuti bentuknya sendiri: He is busy. Jangan menulis He bes."], examples:[{en:"My brother studies English and watches videos.",id:"Saudara laki-laki saya belajar bahasa Inggris dan menonton video.",note:"study → studies; watch → watches."},{en:"We play after class.",id:"Kami bermain setelah kelas.",note:"We tidak mendapat akhiran -s."}]},
      {title:"3. Bentuk negatif, pertanyaan, dan adverb", text:["Untuk tindakan: don't + verb dasar dengan I/you/we/they; doesn't + verb dasar dengan he/she/it. Pertanyaan memakai Do/Does di depan subject. Perhatikan bahwa -s pindah ke does, bukan tetap menempel pada kata kerja.","Always, usually, often, sometimes, dan never biasanya berada sebelum action verb: She often reads. Dengan be, letakkan setelah be: She is often busy."], examples:[{en:"He doesn't drive to work.",id:"Dia tidak berkendara ke tempat kerja.",note:"doesn't + drive, bukan drives."},{en:"Do you usually study at night?",id:"Apakah kamu biasanya belajar malam hari?",note:"Do + subject + usually + verb dasar."}]}
    ],
    mistake:{wrong:"She go to school. / Does he likes music?",right:"She goes to school. / Does he like music?",why:"Kalimat positif he/she/it memakai -s/-es. Dalam pertanyaan, does sudah membawa penanda itu; verb kembali ke bentuk dasar."},
    keyPoints:["Simple present untuk kebiasaan, fakta, dan jadwal.","He/she/it: verb biasanya mendapat -s/-es.","Does/doesn't + verb dasar; adverb frekuensi punya posisi yang berbeda dengan be."],
    check:{question:"Lengkapi: Rina ___ English every evening.",options:["study","studies","is study"],answer:1,explanation:"Rina adalah satu orang (she), sehingga study berubah menjadi studies."}
  },
  {
    id:"present-continuous", category:"Grammar", icon:"⏳", level:"Pemula", minutes:6,
    title:"Present Continuous: kegiatan yang sedang berlangsung",
    summary:"Gunakan am/is/are + verb-ing untuk kegiatan yang terjadi sekarang atau sementara.",
    goals:["Membentuk kalimat be + verb-ing.","Membedakan kegiatan sekarang dan kebiasaan.","Mengetahui perubahan ejaan -ing yang umum."],
    sections:[
      {title:"1. Makna utamanya", text:["Present continuous menyoroti tindakan yang sedang berjalan saat ini atau keadaan sementara di sekitar masa sekarang. Rumusnya: subject + am/is/are + verb-ing. Pilih be seperti biasa: I am; he/she/it is; you/we/they are.","Peristiwa yang sudah direncanakan dalam waktu dekat kadang juga memakai bentuk ini, misalnya We are meeting tomorrow. Untuk awal belajar, fokuslah dahulu pada makna sedang berlangsung."], examples:[{en:"I am reading a story now.",id:"Saya sedang membaca cerita sekarang.",note:"I am + read-ing."},{en:"They are staying with their aunt this week.",id:"Mereka tinggal sementara di rumah bibi minggu ini.",note:"Keadaan sementara."}]},
      {title:"2. Cara menambahkan -ing", text:["Kebanyakan verb cukup ditambah -ing: play → playing, read → reading. Jika verb berakhir e yang tidak dibunyikan, e sering dihilangkan: make → making. Pada beberapa kata pendek berpola konsonan-vokal-konsonan, konsonan akhir digandakan: sit → sitting, run → running. Akhiran -ie berubah menjadi -y: lie → lying.","Ada pengecualian ejaan, jadi gunakan kamus bila ragu. Bentuk ini tetap membutuhkan be; jangan menghilangkan am/is/are."], examples:[{en:"She is making lunch.",id:"Dia sedang menyiapkan makan siang.",note:"make → making; ada is sebelum verb-ing."},{en:"We are sitting near the window.",id:"Kami sedang duduk dekat jendela.",note:"sit → sitting."}]},
      {title:"3. Bedakan dengan simple present", text:["Simple present menjelaskan rutinitas: I read before bed. Present continuous menjelaskan kejadian yang sedang berlangsung: I am reading now. Bandingkan kata petunjuknya, tetapi lihat arti kalimat, bukan hanya satu kata.","Kata kerja keadaan seperti know, believe, need, dan biasanya like lebih sering digunakan dalam simple form ketika menyatakan keadaan: I know the answer, bukan I am knowing the answer. Pemakaian bisa berubah dalam konteks khusus, tetapi pola sederhana ini aman untuk pemula."], examples:[{en:"He usually walks, but today he is taking the bus.",id:"Dia biasanya berjalan kaki, tetapi hari ini dia naik bus.",note:"usually = rutinitas; today = situasi sementara."}]}
    ],
    mistake:{wrong:"They playing football now.",right:"They are playing football now.",why:"Present continuous membutuhkan be sebelum verb-ing."},
    keyPoints:["Rumus: subject + am/is/are + verb-ing.","Untuk tindakan yang berjalan sekarang/sementara; rutinitas biasanya simple present.","Perhatikan ejaan make→making, run→running, lie→lying."],
    check:{question:"Pilih kalimat yang benar untuk kegiatan yang sedang terjadi.",options:["I am write a message now.","I writing a message now.","I am writing a message now."],answer:2,explanation:"Setelah am, gunakan verb-ing: writing."}
  },
  {
    id:"simple-past", category:"Grammar", icon:"🕰️", level:"Pemula–Menengah", minutes:8,
    title:"Simple Past: bercerita tentang masa lalu",
    summary:"Bentuk lampau untuk kejadian yang sudah selesai, termasuk verb regular, irregular, serta pola did/didn't.",
    goals:["Menceritakan peristiwa yang selesai.","Mengenali verb regular dan irregular.","Membuat pertanyaan/negatif dengan did."],
    sections:[
      {title:"1. Kapan memakai simple past?", text:["Gunakan simple past untuk peristiwa yang selesai pada masa lalu. Penanda seperti yesterday, last week, two days ago, atau in 2022 sering membantu menunjukkan waktunya. Dalam cerita, beberapa aksi selesai dapat dirangkai berurutan.","Untuk kata kerja be, gunakan was dengan I/he/she/it dan were dengan you/we/they. Bentuk negatifnya wasn't/weren't, dan pertanyaan memindahkan was/were ke depan."], examples:[{en:"We visited our grandmother last Sunday.",id:"Kami mengunjungi nenek hari Minggu lalu.",note:"visited adalah bentuk lampau regular."},{en:"I was tired, but my friends were cheerful.",id:"Saya lelah, tetapi teman-teman saya ceria.",note:"I was; my friends were."}]},
      {title:"2. Verb regular dan perubahan ejaan", text:["Banyak kata kerja menambah -ed: work → worked, clean → cleaned. Verb yang sudah berakhir e biasanya hanya menambah -d: live → lived. Konsonan + y sering berubah menjadi -ied: study → studied. Ada aturan penggandaan huruf pada beberapa verb pendek: stop → stopped.","Akhiran -ed tidak selalu dibunyikan sama. Pada cleaned bunyinya mendekati /d/, pada watched mendekati /t/, dan pada wanted terdengar satu suku kata tambahan /id/. Panduan ejaan Indonesia hanya pendekatan; dengarkan audio bila tersedia."], examples:[{en:"She studied, cooked, and then watched a film.",id:"Dia belajar, memasak, lalu menonton film.",note:"study→studied; cook→cooked; watch→watched."}]},
      {title:"3. Did untuk pertanyaan dan negatif", text:["Untuk action verb, bentuk pertanyaan memakai Did + subject + verb dasar; negatif memakai didn't + verb dasar. Karena did sudah menandai masa lalu, jangan menambahkan -ed lagi pada verb: Did you go? bukan Did you went?", "Pertanyaan dengan be tidak memakai did: Were you busy? Jawaban pendeknya Yes, I was atau No, I wasn't."], examples:[{en:"Did they see the new teacher?",id:"Apakah mereka melihat guru baru itu?",note:"see tetap bentuk dasar setelah did."},{en:"He didn't bring his notebook.",id:"Dia tidak membawa buku catatannya.",note:"didn't + bring, bukan brought."}]}
    ],
    mistake:{wrong:"Did you went home? / She didn't called me.",right:"Did you go home? / She didn't call me.",why:"Did/didn't sudah menunjukkan waktu lampau, jadi kata kerja utama memakai bentuk dasar."},
    keyPoints:["Simple past menceritakan kejadian yang sudah selesai.","Verb regular sering -ed; verb irregular perlu dipelajari sebagai pasangan.","Did/didn't + verb dasar; be memakai was/were."],
    check:{question:"Pilih pertanyaan yang benar.",options:["Did Mira bought a book?","Did Mira buy a book?","Does Mira bought a book?"],answer:1,explanation:"Did menandai masa lalu; setelahnya gunakan verb dasar buy."}
  },
  {
    id:"asking-questions", category:"Grammar", icon:"❓", level:"Pemula–Menengah", minutes:7,
    title:"Menyusun pertanyaan: do, be, dan question words",
    summary:"Pola pertanyaan ya/tidak dan WH-questions tanpa membalik urutan kata secara keliru.",
    goals:["Memilih pembantu yang cocok untuk jenis verb.","Membuat pertanyaan dengan what/where/when/who/why/how.","Memahami pertanyaan yang menanyakan subject."],
    sections:[
      {title:"1. Pertanyaan ya/tidak", text:["Jika kalimat memakai be, pindahkan be ke awal: You are ready → Are you ready? Jika memakai action verb dalam simple present, gunakan do/does; dalam simple past, gunakan did. Setelah do/does/did, verb utama kembali ke bentuk dasar.","Jawaban pendek memakai pembantu yang sama: Does she live here? Yes, she does. Did they call? No, they didn't."], examples:[{en:"Is your brother at home?",id:"Apakah saudara laki-lakimu di rumah?",note:"Kalimat memakai be, jadi is berpindah ke depan."},{en:"Do you like this book?",id:"Apakah kamu suka buku ini?",note:"like adalah action/state verb non-be, gunakan do."}]},
      {title:"2. WH-question: kata tanya + pola dasar", text:["What menanyakan benda/kegiatan; where tempat; when waktu; who orang; why alasan; how cara/keadaan. Susunan umum: question word + auxiliary/be + subject + main verb. Contoh: Where does Rina study? How are you? What did they eat?", "Jangan menambahkan do jika be sudah menjadi verb utama. Karena itu What is your name? benar, sedangkan What do your name is? salah."], examples:[{en:"When does the bus leave?",id:"Kapan bus berangkat?",note:"When + does + subject + verb dasar."},{en:"Why are they laughing?",id:"Mengapa mereka tertawa?",note:"Pertanyaan sedang berlangsung memakai are + verb-ing."}]},
      {title:"3. Who/what sebagai subject", text:["Jika who atau what sendiri adalah pelaku, biasanya tidak perlu do/did tambahan: Who called you? = Siapa yang meneleponmu? Who adalah subject dari called. Bandingkan Who did you call? = Kamu menelepon siapa? Di sini you adalah subject, dan who adalah object sehingga did digunakan.","Dalam percakapan sopan, pertanyaan bisa diperhalus dengan Could you tell me…? atau Would you mind…? Setelah ungkapan itu, susunan bagian berikutnya seperti kalimat biasa: Could you tell me where the station is?"], examples:[{en:"Who opened the window? / Who did you invite?",id:"Siapa yang membuka jendela? / Kamu mengundang siapa?",note:"Pertama who=subject; kedua who=object."}]}
    ],
    mistake:{wrong:"Where you live? / What does she wants?",right:"Where do you live? / What does she want?",why:"Action verb pada simple present memerlukan do/does; setelah does verb tidak mendapat -s."},
    keyPoints:["Be berpindah ke depan subject; action verb memakai do/does/did.","WH-word berada di awal, diikuti pola auxiliary + subject + verb.","Who sebagai pelaku sering tidak memerlukan do/did."],
    check:{question:"Kalimat mana yang menanyakan tempat tinggal Rina dengan benar?",options:["Where Rina lives?","Where does Rina live?","Where do Rina lives?"],answer:1,explanation:"Rina = she, gunakan does; verb setelah does adalah live."}
  },
  {
    id:"articles", category:"Grammar", icon:"📚", level:"Pemula–Menengah", minutes:8,
    title:"A, an, the, dan kapan tanpa artikel",
    summary:"Pilih artikel berdasarkan jumlah benda, bunyi awal kata, dan apakah benda sudah diketahui pembaca.",
    goals:["Memakai a/an untuk satu benda countable yang belum spesifik.","Menggunakan the untuk benda tertentu/diketahui.","Mengetahui kapan kata benda plural/general tanpa artikel."],
    sections:[
      {title:"1. A dan an: satu benda yang belum spesifik", text:["A/an hanya dipakai dengan kata benda tunggal yang dapat dihitung. A book berarti sebuah buku, belum tentu buku yang mana. Pilih berdasarkan bunyi awal kata setelahnya, bukan sekadar huruf: an apple, an hour (h tidak terdengar), tetapi a university (awal bunyinya seperti /y/). Jika ada adjective, lihat kata setelah artikel: an interesting story.","Bentuk plural atau kata benda tak terhitung tidak langsung memakai a/an: books, water. Gunakan penentu lain bila perlu, seperti some books atau a glass of water."], examples:[{en:"She found an old coin and a small box.",id:"Dia menemukan sebuah koin tua dan sebuah kotak kecil.",note:"old diawali bunyi vokal; small diawali bunyi konsonan."}]},
      {title:"2. The: benda tertentu atau sudah diketahui", text:["Gunakan the saat pembicara dan pendengar bisa mengenali benda yang dimaksud: benda itu sudah disebut, hanya ada satu dalam konteks, atau dijelaskan secara spesifik. The dapat dipakai untuk tunggal, plural, dan kata benda uncountable jika spesifik.","Contoh alur: I saw a cat. The cat was sleeping. Pertama kali diperkenalkan sebagai a cat; penyebutan berikutnya sebagai the cat karena kini sudah diketahui."], examples:[{en:"Please close the door next to you.",id:"Tolong tutup pintu yang berada di sebelahmu.",note:"Pintu tertentu ditunjuk oleh keterangan next to you."}]},
      {title:"3. Tanpa artikel untuk makna umum", text:["Kata benda plural atau uncountable sering tanpa the ketika membicarakan sesuatu secara umum: Books can teach us; Water is important. Jika yang dimaksud spesifik, gunakan the: The books on this desk are mine; The water in this bottle is cold.","Nama orang dan kebanyakan nama kota/negara biasanya tanpa the, tetapi ada nama khusus yang memakai the. Pelajari sebagai nama tetap, bukan aturan yang harus ditebak."], examples:[{en:"Children need sleep. The children in this class are quiet.",id:"Anak-anak membutuhkan tidur. Anak-anak di kelas ini tenang.",note:"Pernyataan umum tanpa artikel; kelompok tertentu memakai the."}]}
    ],
    mistake:{wrong:"I have a water. / She is an university student.",right:"I have some water. / She is a university student.",why:"Water biasanya uncountable sehingga tidak memakai a langsung. University diawali bunyi /y/, jadi memakai a."},
    keyPoints:["A/an untuk satu countable noun yang belum spesifik.","The untuk benda tertentu atau sudah dikenal.","Plural/uncountable general sering tidak memakai artikel."],
    check:{question:"Pilih bentuk yang benar.",options:["an university","a university","the university"],answer:1,explanation:"Untuk penyebutan umum satu universitas, bunyi awal university seperti /y/, jadi a university."}
  },
  {
    id:"pronouns", category:"Grammar", icon:"👥", level:"Pemula", minutes:6,
    title:"Pronoun dan kepemilikan: I, me, my, mine",
    summary:"Bedakan kata ganti sebagai pelaku, penerima tindakan, penanda kepemilikan, dan kata milik mandiri.",
    goals:["Memilih subject atau object pronoun.","Membedakan my dengan mine dan bentuk lain.","Menempatkan pronoun pada posisi yang tepat."],
    sections:[
      {title:"1. Subject dan object pronoun", text:["Subject pronoun melakukan atau mengalami tindakan sebagai subject: I, you, he, she, it, we, they. Object pronoun menerima tindakan atau muncul setelah preposition: me, you, him, her, it, us, them. Susunan dasarnya: She called me, bukan Her called I.","Untuk dua orang, sebutkan masing-masing dengan bentuk yang benar: Rina and I are classmates; The teacher helped Rina and me."], examples:[{en:"They invited us to the library.",id:"Mereka mengundang kami ke perpustakaan.",note:"They = subject; us = object."}]},
      {title:"2. Kata sifat kepemilikan dan kata milik mandiri", text:["My, your, his, her, its, our, their selalu diikuti kata benda: my bag, their house. Mine, yours, his, hers, ours, theirs dapat berdiri sendiri menggantikan kata benda: This bag is mine. Jangan gabungkan mine bag.","Possessive pronoun tidak memakai apostrof: yours, hers, theirs. Its berarti miliknya (benda/hewan), sedangkan it's adalah singkatan it is atau it has."], examples:[{en:"That is her notebook; the blue one is mine.",id:"Itu buku catatannya; yang biru milik saya.",note:"her + noun; mine berdiri sendiri."}]},
      {title:"3. Refleksif dan rujukan yang jelas", text:["Myself, yourself, himself, herself, itself, ourselves, yourselves, themselves dipakai jika pelaku dan penerima tindakan orang/benda yang sama: He taught himself. Bentuk ini juga dapat memberi penekanan: I made it myself.","Pastikan pembaca tahu pronoun merujuk siapa. Dalam kalimat panjang, ulangi nama jika penggunaan he/she/they bisa membingungkan."], examples:[{en:"The students introduced themselves.",id:"Para siswa memperkenalkan diri mereka sendiri.",note:"Students melakukan dan menerima tindakan yang sama."}]}
    ],
    mistake:{wrong:"Me and Bimo are friends. / This is mine book.",right:"Bimo and I are friends. / This is my book.",why:"Sebagai subject gunakan I; sebelum kata benda gunakan my. Mine dipakai tanpa kata benda sesudahnya."},
    keyPoints:["Subject: I/he/she/we/they; object: me/him/her/us/them.","My/your/their + noun; mine/yours/theirs berdiri sendiri.","Its tanpa apostrof adalah kepemilikan; it's berarti it is/it has."],
    check:{question:"Lengkapi: The coach spoke to Naya and ___.",options:["I","me","my"],answer:1,explanation:"Setelah preposition to, gunakan object pronoun me."}
  },
  {
    id:"prepositions", category:"Grammar", icon:"📍", level:"Pemula–Menengah", minutes:8,
    title:"Preposisi waktu dan tempat: in, on, at",
    summary:"Pahami pola umum in/on/at untuk waktu dan lokasi, serta gunakan sebagai peta awal, bukan hafalan tanpa konteks.",
    goals:["Memilih preposisi waktu berdasarkan luas waktunya.","Membedakan lokasi umum, permukaan, dan titik tertentu.","Mengenali beberapa pasangan frasa yang umum."],
    sections:[
      {title:"1. Waktu: rentang luas, hari/tanggal, jam", text:["Sebagai aturan awal, in dipakai untuk rentang luas: in 2026, in July, in the morning. On dipakai untuk hari atau tanggal: on Monday, on 12 May. At dipakai untuk waktu yang spesifik: at 7:30, at noon, at night.","Ini pola umum, bukan aturan tanpa pengecualian. Frasa tetap seperti at the weekend (variasi British) dan on the weekend (variasi American) berbeda menurut dialek. Hafalkan frasa yang sering kamu butuhkan."], examples:[{en:"Our class starts at 8 on Monday.",id:"Kelas kami mulai pukul 8 pada hari Senin.",note:"Jam tertentu = at; hari = on."},{en:"My birthday is in September.",id:"Ulang tahun saya pada bulan September.",note:"Bulan = in."}]},
      {title:"2. Tempat: area, permukaan, dan titik", text:["Untuk tempat, in sering menandai area/ruang yang di dalamnya: in a room, in a city. On sering menandai permukaan atau jalur: on the table, on the wall, on this street. At sering memandang lokasi sebagai titik/kegiatan: at the bus stop, at school, at the entrance.","Bayangkan fokus maknanya: ruang di dalam, permukaan, atau titik lokasi. Ada frasa tetap yang perlu diingat, misalnya at home, in bed, on a bus. Jangan menerjemahkan preposisi satu per satu dari bahasa Indonesia."], examples:[{en:"The keys are on the table in the kitchen.",id:"Kuncinya berada di atas meja di dapur.",note:"on = permukaan; in = ruang."},{en:"Meet me at the library entrance.",id:"Temui saya di pintu masuk perpustakaan.",note:"at menunjuk titik pertemuan tertentu."}]},
      {title:"3. Gerakan: to, into, dan onto", text:["To menunjukkan arah/tujuan: walk to school. Into menekankan gerakan masuk ke dalam: go into the room. Onto menekankan gerakan menuju permukaan: put the cup onto the shelf. Jika hanya menyebut lokasi tanpa gerakan, gunakan preposisi lokasi yang sesuai.","Pola ini membantu membuat gambaran mental, tetapi pasangan kata tertentu tetap mengikuti kebiasaan bahasa Inggris."], examples:[{en:"She walked into the classroom and put her bag on a chair.",id:"Dia berjalan masuk ke ruang kelas dan menaruh tasnya di atas kursi.",note:"into = gerakan masuk; on = berada di permukaan."}]}
    ],
    mistake:{wrong:"I was born on 2009. / The book is in the table.",right:"I was born in 2009. / The book is on the table.",why:"Tahun biasanya memakai in. Buku di permukaan meja memakai on; jika berada di dalam laci, gunakan in."},
    keyPoints:["Waktu: in + bulan/tahun, on + hari/tanggal, at + jam/titik waktu.","Tempat: in untuk ruang/area, on untuk permukaan/jalur, at untuk titik/lokasi.","Ingat frasa tetap dan periksa contoh nyata saat ragu."],
    check:{question:"Pilih preposisi: The meeting is ___ Friday ___ 3 p.m.",options:["in / on","on / at","at / in"],answer:1,explanation:"Hari memakai on; jam tertentu memakai at."}
  },
  {
    id:"modal-verbs", category:"Grammar", icon:"🧭", level:"Menengah", minutes:7,
    title:"Can, could, should, must, dan have to",
    summary:"Gunakan modal untuk kemampuan, permintaan, saran, kemungkinan, dan kewajiban tanpa mengubah bentuk verb setelahnya.",
    goals:["Memilih modal sesuai maksud.","Menggunakan modal + verb dasar.","Memahami beda saran dan kewajiban."],
    sections:[
      {title:"1. Kemampuan dan permintaan", text:["Can menyatakan kemampuan atau izin informal: I can swim; Can I leave? Could dapat menyatakan kemampuan masa lalu atau permintaan yang lebih sopan: Could you help me? Bentuk could dalam permintaan tidak selalu berarti masa lalu.","Setelah can/could, gunakan verb dasar tanpa to dan tanpa -s. Pertanyaan dibuat dengan memindahkan modal ke depan; tidak perlu do."], examples:[{en:"Bimo can explain the rule.",id:"Bimo bisa menjelaskan aturan itu.",note:"can + explain, bukan explains/to explain."},{en:"Could you repeat that, please?",id:"Bisakah Anda mengulanginya, tolong?",note:"Permintaan sopan."}]},
      {title:"2. Saran dan kewajiban", text:["Should memberi saran atau menyatakan hal yang sebaiknya dilakukan: You should rest. Must menyatakan kewajiban/keharusan yang kuat menurut pembicara atau aturan. Have to juga menyatakan keharusan, sering karena aturan atau keadaan dari luar: I have to wear a uniform.","Bentuk have to berubah sesuai subject: she has to; pertanyaan simple present memakai Does she have to…? Kata mustn't berarti dilarang, sedangkan don't have to berarti tidak wajib—dua makna ini berbeda."], examples:[{en:"You should check your answer. Students mustn't use phones during the test.",id:"Kamu sebaiknya memeriksa jawaban. Siswa dilarang memakai ponsel saat ujian.",note:"should = saran; mustn't = larangan."}]},
      {title:"3. Negatif dan pertanyaan", text:["Untuk modal, letakkan not setelah modal: cannot/can't, shouldn't, mustn't. Pertanyaan: Should we start? Can she join? Untuk have to, gunakan do/does: Do we have to bring a book?", "Gunakan nada yang sesuai situasi. Can I…? biasa dan langsung; Could I…? lebih halus. Aturan kesopanan dapat berbeda menurut konteks dan hubungan pembicara."], examples:[{en:"You don't have to finish it today.",id:"Kamu tidak harus menyelesaikannya hari ini.",note:"Tidak wajib bukan berarti dilarang."}]}
    ],
    mistake:{wrong:"She can sings. / You mustn't come tomorrow (padahal maksudnya tidak wajib).",right:"She can sing. / You don't have to come tomorrow.",why:"Modal + verb dasar. Mustn't berarti dilarang; don't have to berarti tidak perlu/wajib."},
    keyPoints:["Can/could/should/must + verb dasar tanpa to dan tanpa -s.","Should = saran; must/have to = kewajiban; mustn't = larangan.","Don't have to berarti tidak wajib, bukan dilarang."],
    check:{question:"Kamu memberi saran agar teman beristirahat. Pilih bentuk tepat.",options:["You should rest.","You should to rest.","You should rests."],answer:0,explanation:"Should diikuti verb dasar tanpa to dan tanpa -s."}
  },
  {
    id:"countable-nouns", category:"Grammar", icon:"🍎", level:"Pemula–Menengah", minutes:7,
    title:"Countable dan uncountable nouns",
    summary:"Pilih many, much, some, any, a few, atau a little berdasarkan cara benda dihitung.",
    goals:["Membedakan kata benda yang dapat dihitung satu per satu.","Memakai quantifier yang sesuai.","Menggunakan satuan untuk kata benda uncountable."],
    sections:[
      {title:"1. Dapat dihitung atau tidak?", text:["Countable nouns dapat dihitung satu per satu dan punya bentuk tunggal/jamak: one apple, three apples. Bentuk tunggal biasanya membutuhkan penentu: an apple, the apple, my apple. Uncountable nouns dipandang sebagai bahan, cairan, atau gagasan: water, rice, information, advice. Biasanya tidak memakai a/an langsung dan tidak ditambah -s untuk makna umum.","Beberapa kata dapat berubah menurut arti: chicken sebagai hewan dapat dihitung; chicken sebagai daging biasanya uncountable. Pelajari kata dalam konteks kalimat."], examples:[{en:"We bought three oranges and some rice.",id:"Kami membeli tiga jeruk dan sedikit/seporsi beras.",note:"oranges dapat dihitung; rice tidak dihitung satu per satu."}]},
      {title:"2. Many/much dan some/any", text:["Many cocok dengan countable plural: many books. Much cocok dengan uncountable: much time. Dalam percakapan positif, a lot of dapat dipakai dengan keduanya: a lot of friends, a lot of water.","Some sering muncul pada kalimat positif dan tawaran/permintaan; any sering pada pertanyaan dan negatif. Ini kecenderungan, bukan aturan mutlak: Would you like some tea? adalah tawaran yang alami."], examples:[{en:"Are there any chairs? We don't have much time.",id:"Apakah ada kursi? Kami tidak punya banyak waktu.",note:"any + plural countable; much + uncountable."}]},
      {title:"3. A few/a little dan satuan", text:["A few berarti beberapa dan dipakai dengan countable plural; a little berarti sedikit/sejumlah dan dipakai dengan uncountable. Tanpa a, few/little sering menekankan jumlah yang hampir tidak cukup. Makna rasa ini membantu memilih sesuai maksud.","Agar uncountable bisa dihitung, tambahkan satuan: a glass of water, two bowls of rice, three pieces of advice. Kata benda setelah satuan dapat tetap uncountable: two pieces of information."], examples:[{en:"I have a few questions and a little free time.",id:"Saya punya beberapa pertanyaan dan sedikit waktu luang.",note:"questions countable; time uncountable."}]}
    ],
    mistake:{wrong:"many water / an advice / two informations",right:"much water / a piece of advice / two pieces of information",why:"Water, advice, dan information biasanya uncountable dalam makna ini; gunakan quantifier atau satuan."},
    keyPoints:["Many/a few dengan countable plural; much/a little dengan uncountable.","Some/any mengikuti konteks kalimat.","Gunakan satuan seperti a cup of, a piece of, atau a bottle of."],
    check:{question:"Pilih frasa yang benar.",options:["many information","a few information","a little information"],answer:2,explanation:"Information biasanya uncountable, jadi gunakan a little information."}
  },
  {
    id:"word-chunks", category:"Kosakata", icon:"🧠", level:"Semua tingkat", minutes:6,
    title:"Cara mengingat kosakata lebih lama",
    summary:"Belajar kata lewat pengulangan berjeda, contoh kalimat, word family, dan pasangan kata yang alami.",
    goals:["Mencatat kosakata dengan konteks.","Melatih ingatan aktif, bukan hanya membaca ulang.","Mengenali collocation dan word family."],
    sections:[
      {title:"1. Simpan kata bersama konteks", text:["Catat kata baru dalam bentuk yang benar-benar kamu butuhkan: makna inti, contoh kalimat pendek, dan satu pasangan kata yang umum. Misalnya make a decision dan do homework. Terjemahan satu kata sering tidak cukup karena satu kata Inggris bisa punya beberapa arti menurut konteks.","Batasi jumlah kata baru per sesi. Lima sampai sepuluh kata yang dipahami dan dapat dipakai biasanya lebih berguna daripada daftar panjang yang hanya dibaca sekali."], examples:[{en:"I made a decision after talking to my teacher.",id:"Saya membuat keputusan setelah berbicara dengan guru saya.",note:"make a decision adalah pasangan kata yang umum."}]},
      {title:"2. Pengulangan berjeda dan active recall", text:["Jangan hanya menatap catatan berulang kali. Tutup arti, lihat kata Inggris, lalu coba ingat artinya dan buat satu kalimat. Setelah itu cek jawaban. Ulangi pada hari yang sama, esok hari, beberapa hari kemudian, lalu minggu berikutnya. Jarak pengulangan dapat disesuaikan bila kata masih sulit.","Kesalahan saat mengingat bukan kegagalan; itu petunjuk kata mana yang perlu dilatih lagi. Tandai kata yang sulit dan buat contoh yang dekat dengan kehidupanmu."], bullets:["Lihat kata → coba ingat tanpa bantuan.","Buat contoh kalimat sederhana.","Cek arti dan koreksi bentuknya.","Ulangi dengan jarak waktu yang makin panjang."]},
      {title:"3. Word family dan collocation", text:["Perhatikan keluarga kata: teach (verb), teacher (noun), teaching (kegiatan/gerund). Akhiran seperti -er, -ful, -less, dan -tion memberi petunjuk, tetapi tidak semua perubahan bisa ditebak; periksa kamus jika bentuknya baru.","Pelajari frasa, bukan kata yang terpisah: take a photo, catch a bus, interested in. Menyimpan frasa membantu kamu membangun kalimat yang lebih alami."], examples:[{en:"The teacher gave us useful advice.",id:"Guru itu memberi kami saran yang berguna.",note:"teacher adalah word family; give advice adalah pasangan kata."}]}
    ],
    mistake:{wrong:"Menghafal satu kata tanpa contoh lalu berharap selalu cocok di semua kalimat.",right:"Catat kata, makna sesuai konteks, pasangan kata, dan satu contoh buatan sendiri.",why:"Konteks memperlihatkan cara pakai, grammar, dan pasangan kata alami."},
    keyPoints:["Belajar sedikit tetapi aktif dan berulang.","Simpan kata dalam kalimat dan collocation.","Gunakan jeda, tes ingatan, lalu cek dan koreksi."],
    check:{question:"Cara mana yang paling membantu kata bertahan lama?",options:["Membaca daftar sekali tanpa mencoba mengingat.","Menutup catatan, mencoba mengingat, membuat kalimat, lalu mengecek.","Menghafal terjemahan tanpa konteks."],answer:1,explanation:"Active recall ditambah contoh dan pengulangan berjeda memperkuat ingatan serta cara penggunaan."}
  },
  {
    id:"word-building", category:"Kosakata", icon:"🧩", level:"Menengah", minutes:7,
    title:"Mengenali word family dan potongan kata",
    summary:"Gunakan akar kata, prefix, dan suffix sebagai petunjuk makna tanpa menganggap semua kata dapat ditebak sempurna.",
    goals:["Mengenali beberapa suffix pembentuk kelas kata.","Memakai prefix umum sebagai petunjuk awal.","Memeriksa bentuk dan makna melalui konteks."],
    sections:[
      {title:"1. Akar kata dan perubahan kelas kata", text:["Satu akar dapat membentuk beberapa kata. Help dapat menjadi helpful (adjective), helpless (adjective dengan makna berbeda), atau helper (noun). Teach dapat menjadi teacher dan teaching. Perubahan akhiran sering memberi petunjuk apakah kata berfungsi sebagai noun, verb, adjective, atau adverb.","Akhiran bukan rumus mutlak. Ada ejaan yang berubah dan ada bentuk yang tidak mengikuti pola umum, jadi gunakan kamus untuk memastikan."], examples:[{en:"Her explanation was helpful.",id:"Penjelasannya membantu.",note:"Help berubah menjadi helpful, sebuah adjective."}]},
      {title:"2. Prefix sebagai petunjuk makna", text:["Beberapa prefix cukup umum: un- sering menyatakan kebalikan (unhappy), re- dapat berarti mengulang (rewrite), dis- dapat menunjukkan kebalikan/peniadaan (disagree), dan pre- berarti sebelum (preview). Prefix tidak selalu bisa ditempelkan pada kata apa pun.","Jika menemukan kata baru, coba pisahkan bagian yang dikenal, lalu baca seluruh kalimat untuk menguji dugaanmu. Jangan mengandalkan potongan kata saja karena beberapa kata tampak mirip tetapi sejarah/maknanya berbeda."], examples:[{en:"Please reread the instructions before you start.",id:"Tolong baca ulang petunjuk sebelum mulai.",note:"re- memberi petunjuk bahwa read dilakukan lagi."}]},
      {title:"3. Tebak cerdas, lalu verifikasi", text:["Gunakan tiga langkah: cari bagian kata yang dikenal, lihat posisi kata di kalimat, kemudian pilih makna yang paling masuk akal. Misalnya, setelah a very…, kata berikutnya sering adjective atau adverb; setelah the…, sering noun atau adjective + noun.","Catat bentuk dasar dan bentuk turunannya dalam satu kelompok. Sertakan contoh agar kamu tidak hanya mengingat arti, tetapi juga grammar dan pemakaian."], bullets:["Bagian kata = petunjuk awal.","Grammar di sekitar kata = petunjuk kelas kata.","Konteks kalimat = pengecek makna.","Kamus/contoh tepercaya = verifikasi akhir."]}
    ],
    mistake:{wrong:"Menganggap un- selalu membuat kata yang benar dan berlawanan.",right:"Gunakan prefix sebagai petunjuk, lalu cek kata dan contoh pemakaiannya.",why:"Tidak semua kata menerima prefix yang sama; bentuk yang terdengar masuk akal belum tentu digunakan."},
    keyPoints:["Akar kata dapat membentuk keluarga kata dengan fungsi berbeda.","Prefix/suffix membantu menebak, tetapi tidak menjamin makna.","Periksa kelas kata, konteks, dan contoh kamus."],
    check:{question:"Apa cara aman saat menebak arti kata baru dari prefix?",options:["Anggap tebakan pasti benar.","Gunakan prefix dan konteks sebagai petunjuk, lalu verifikasi.","Abaikan kalimat di sekitarnya."],answer:1,explanation:"Prefix membantu membuat dugaan; konteks dan kamus digunakan untuk memastikan."}
  },
  {
    id:"pronunciation", category:"Speaking", icon:"🗣️", level:"Pemula–Menengah", minutes:8,
    title:"Pelafalan: tekanan kata, akhiran, dan latihan dengar-ucap",
    summary:"Latih kejelasan melalui suku kata, word stress, akhiran -s/-ed, dan shadowing sederhana.",
    goals:["Mendengar suku kata yang mendapat tekanan.","Mengenali variasi bunyi akhiran -s dan -ed.","Berlatih dengan potongan pendek, bukan bicara cepat."],
    sections:[
      {title:"1. Suku kata dan tekanan kata", text:["Kata panjang biasanya punya satu suku kata yang terdengar lebih menonjol. Tekanan membantu pendengar mengenali kata. Dengarkan kata dari audio kamus atau voice perangkat, lalu tepuk suku kata pelan: TAble, beGIN, imPORtant. Huruf besar di sini hanya penanda latihan, bukan ejaan resmi.","Panduan bunyi dengan ejaan Indonesia hanya perkiraan. Bunyi English tertentu tidak sama persis dengan huruf Indonesia, jadi gunakan model audio dan tirukan pelan-pelan."], examples:[{en:"The first syllable is stressed in TEAcher.",id:"Suku kata pertama mendapat tekanan pada kata teacher.",note:"Ucapkan TEA lebih menonjol, bukan semua bagian dengan tekanan sama."}]},
      {title:"2. Akhiran -s dan -ed", text:["Akhiran jamak atau orang ketiga -s bisa terdengar seperti /s/ setelah bunyi tak bersuara (cats), seperti /z/ setelah bunyi bersuara (dogs), atau /iz/ setelah bunyi seperti s/sh/ch (buses, watches). Perbedaan ini sering membantu kata terdengar jelas.","Akhiran -ed pada past tense juga punya tiga pola umum: bunyi /t/ (watched), /d/ (played), atau tambahan suku kata /id/ (wanted). Jangan selalu membunyikannya sebagai satu suku kata ekstra."], examples:[{en:"She watches two cats and walks two dogs.",id:"Dia menonton dua kucing dan berjalan dengan dua anjing.",note:"Latih akhiran kata secara perlahan dan jelas."},{en:"I wanted a book and watched a film.",id:"Saya menginginkan sebuah buku dan menonton film.",note:"wanted punya suku kata tambahan; watched tidak."}]},
      {title:"3. Shadowing aman untuk pemula", text:["Pilih satu kalimat pendek. Dengarkan sekali untuk makna, dengarkan lagi sambil memperhatikan jeda, lalu tirukan satu potongan pada satu waktu. Rekam suara sendiri jika nyaman, bandingkan kejelasan kata, bukan untuk mengejar aksen tertentu.","Dalam ucapan alami, kata dapat tersambung dan beberapa bunyi lemah. Mulailah dengan lambat, pertahankan akhir kata, lalu tingkatkan kecepatan sedikit demi sedikit. Tidak perlu meniru aksen penutur tertentu untuk bisa dipahami."], bullets:["Dengar kalimat dan pahami makna.","Tandai satu kata yang ingin diperjelas.","Tirukan 3–5 kali dengan santai.","Jeda, lalu coba lagi tanpa melihat teks."]}
    ],
    mistake:{wrong:"Mempercepat ucapan dan menghilangkan akhir kata agar terdengar seperti native.",right:"Utamakan bunyi akhir, tekanan kata, dan tempo yang nyaman.",why:"Kejelasan lebih penting daripada kecepatan atau meniru aksen tertentu."},
    keyPoints:["Gunakan audio untuk mengecek tekanan; ejaan pelafalan lokal hanya pendekatan.","Perhatikan variasi -s dan -ed.","Shadowing: dengar, pecah pendek, tiru, lalu coba tanpa teks."],
    check:{question:"Berapa pola bunyi umum untuk akhiran regular -ed?",options:["Satu pola saja, selalu dibaca ed.","Tiga pola umum: /t/, /d/, dan /id/.","Tidak pernah terdengar."],answer:1,explanation:"Akhiran -ed memiliki tiga pola bunyi umum yang dipengaruhi bunyi terakhir kata."}
  },
  {
    id:"conversation", category:"Speaking", icon:"💬", level:"Pemula", minutes:6,
    title:"Ungkapan percakapan: menyapa, meminta ulang, dan merespons",
    summary:"Gunakan frasa sederhana agar percakapan tetap berjalan walaupun belum tahu semua kosakata.",
    goals:["Memulai percakapan dengan sapaan yang sesuai.","Meminta lawan bicara mengulang atau berbicara lebih pelan.","Menjawab singkat lalu menambahkan satu detail."],
    sections:[
      {title:"1. Sapaan dan jawaban singkat", text:["Sesuaikan sapaan dengan situasi. Hi/Hello cocok untuk banyak keadaan. Good morning dipakai pagi; Good afternoon siang/sore; Good evening saat menyapa malam. How are you? dapat dijawab I'm good, thanks. How about you? atau I'm a little tired, but I'm okay.","Untuk perkenalan, gunakan My name is… atau I'm… lalu tanyakan And you? atau What's your name? Dalam situasi formal, pilih sapaan dan nada yang lebih sopan."], examples:[{en:"Hi, I'm Naya. Nice to meet you.",id:"Hai, saya Naya. Senang bertemu denganmu.",note:"Perkenalan singkat dan ramah."}]},
      {title:"2. Jangan berhenti saat tidak paham", text:["Meminta bantuan adalah bagian normal dari percakapan. Ucapkan Could you repeat that, please? untuk meminta pengulangan; Could you speak more slowly? untuk meminta tempo lebih pelan; What does … mean? untuk menanyakan arti.","Jika hanya satu bagian yang terlewat, sebutkan bagian itu: Did you say fifteen or fifty? Konfirmasi membantu mengurangi salah dengar."], examples:[{en:"Sorry, could you say that again more slowly?",id:"Maaf, bisakah Anda mengatakannya lagi dengan lebih pelan?",note:"Frasa sopan untuk memperbaiki pemahaman."}]},
      {title:"3. Perpanjang jawaban satu langkah", text:["Jika seseorang bertanya What do you like? jawaban satu kata seperti Music benar, tetapi kamu bisa menambah satu kalimat: I like pop music because it helps me relax. Polanya: jawaban + detail/contoh/alasan + pertanyaan balik.","Gunakan ungkapan penyangga bila perlu berpikir: Let me think. / That's a good question. Beri jeda yang wajar; tidak perlu mengisi setiap detik dengan kata."], examples:[{en:"I enjoy reading because I learn new ideas. What do you enjoy?",id:"Saya suka membaca karena belajar gagasan baru. Kamu suka apa?",note:"Jawaban diberi alasan dan diakhiri pertanyaan balik."}]}
    ],
    mistake:{wrong:"Berpura-pura paham padahal melewatkan informasi penting.",right:"Sopan meminta pengulangan, penjelasan, atau tempo lebih pelan.",why:"Klarifikasi mencegah salah paham dan justru membantu percakapan berjalan."},
    keyPoints:["Sapaan menyesuaikan waktu dan situasi.","Frasa klarifikasi sangat berguna bagi pembelajar.","Tambahkan satu detail dan ajukan pertanyaan balik."],
    check:{question:"Lawan bicara berbicara terlalu cepat. Ungkapan mana yang paling sesuai?",options:["Could you speak more slowly, please?","I don't listening.","Speak English now."],answer:0,explanation:"Ungkapan pertama meminta tempo lebih pelan dengan sopan."}
  },
  {
    id:"reading", category:"Reading", icon:"🔎", level:"Semua tingkat", minutes:6,
    title:"Strategi membaca: pahami inti tanpa menerjemahkan semua kata",
    summary:"Gunakan preview, skimming, scanning, dan konteks untuk membaca teks lebih efisien.",
    goals:["Mencari gambaran umum sebelum membaca detail.","Menemukan informasi tertentu dengan cepat.","Menebak arti kata dari konteks secara hati-hati."],
    sections:[
      {title:"1. Lihat bentuk teks terlebih dahulu", text:["Sebelum membaca kata demi kata, amati judul, subjudul, gambar, kata yang ditebalkan, dan panjang paragraf. Tanyakan: topik ini tentang apa? Untuk siapa? Informasi apa yang mungkin dicari? Preview memberi kerangka sehingga detail lebih mudah dipahami.","Skimming berarti membaca cepat untuk menangkap gagasan utama: lihat judul, kalimat pembuka, kata kunci, dan penutup. Tidak perlu memahami setiap kata."], examples:[{en:"Read the title and first sentence before reading the whole article.",id:"Baca judul dan kalimat pertama sebelum membaca seluruh artikel.",note:"Langkah preview membantu menebak topik."}]},
      {title:"2. Scanning untuk fakta tertentu", text:["Scanning berarti mencari informasi tertentu seperti nama, tanggal, angka, atau lokasi. Tentukan dulu yang dicari, lalu gerakkan pandangan ke kata yang bentuknya mudah dikenali. Setelah menemukannya, baca kalimat di sekitarnya agar konteksnya tepat.","Jangan memakai scanning untuk memahami argumen utama; gunakan skimming atau baca teliti sesuai tujuan."], examples:[{en:"Find the date 12 May in the notice, then read the sentence around it.",id:"Temukan tanggal 12 Mei pada pengumuman, lalu baca kalimat di sekitarnya.",note:"Cari fakta spesifik, kemudian cek konteks."}]},
      {title:"3. Menghadapi kosakata yang belum dikenal", text:["Coba tebak peran kata dari grammar dan konteks. Perhatikan kata penghubung seperti but, because, however, atau contoh setelah such as. Jika satu kata tidak menghalangi makna utama, tandai dan lanjutkan dahulu.","Setelah menyelesaikan paragraf, cek kata penting di kamus dan tulis contoh. Hindari menerjemahkan seluruh kalimat terlalu cepat: terjemahan kata demi kata sering membuat susunan makna kacau."], bullets:["Baca paragraf satu kali untuk gagasan utama.","Lingkari maksimal beberapa kata penting.","Gunakan konteks untuk membuat dugaan.","Periksa dugaan dan baca ulang kalimat."]}
    ],
    mistake:{wrong:"Berhenti di setiap kata asing dan menerjemahkan satu per satu sebelum tahu topik.",right:"Baca untuk tujuan tertentu, gunakan konteks, lalu cek kata kunci setelahnya.",why:"Menerjemahkan terlalu dini mengganggu alur dan belum tentu menghasilkan makna yang alami."},
    keyPoints:["Preview dan skimming untuk memahami inti.","Scanning untuk mencari fakta khusus.","Gunakan konteks, lalu verifikasi kata penting."],
    check:{question:"Kamu ingin menemukan nomor telepon di sebuah pengumuman. Strategi apa yang cocok?",options:["Scanning","Menebak seluruh teks","Menerjemahkan semua kata dulu"],answer:0,explanation:"Scanning digunakan untuk menemukan detail spesifik seperti nomor, nama, dan tanggal."}
  },
  {
    id:"writing-paragraph", category:"Writing", icon:"✍️", level:"Pemula–Menengah", minutes:8,
    title:"Menulis paragraf sederhana yang runtut",
    summary:"Susun satu gagasan utama, dukung dengan detail, gunakan penghubung, lalu periksa tulisan.",
    goals:["Menentukan satu topik untuk satu paragraf.","Menyusun topic sentence dan kalimat pendukung.","Memeriksa kapital, tanda baca, dan subject-verb agreement."],
    sections:[
      {title:"1. Satu paragraf, satu gagasan utama", text:["Mulai dengan topic sentence yang memberi tahu pembaca inti paragraf. Lanjutkan dengan dua atau tiga detail, alasan, contoh, atau pengalaman. Kalimat penutup dapat merangkum atau menunjukkan hasilnya. Urutkan ide: umum dahulu, lalu detail.","Jangan memasukkan banyak topik yang tidak berkaitan dalam satu paragraf. Jika gagasan berubah, mulai paragraf baru."], examples:[{en:"I enjoy our school library. It is quiet, the books are organized, and I can study with my friends. I often go there after class.",id:"Saya suka perpustakaan sekolah. Tempatnya tenang, buku-bukunya tertata, dan saya bisa belajar bersama teman. Saya sering ke sana setelah kelas.",note:"Kalimat pertama menyatakan topik; kalimat berikutnya mendukungnya."}]},
      {title:"2. Gunakan penghubung dengan tepat", text:["And menambahkan ide; but menunjukkan kontras; because memberi alasan; so menunjukkan hasil; first/next/finally mengurutkan langkah. Pilih kata penghubung karena hubungan maknanya, bukan untuk menghias setiap kalimat.","Pakai kalimat sederhana terlebih dahulu. Dua kalimat jelas lebih baik daripada satu kalimat panjang yang membuat subject dan verb sulit ditemukan."], examples:[{en:"I wanted to play outside, but it was raining, so I stayed home.",id:"Saya ingin bermain di luar, tetapi hujan, jadi saya tinggal di rumah.",note:"but = kontras; so = hasil."}]},
      {title:"3. Checklist revisi", text:["Periksa kapital di awal kalimat dan untuk nama/hari/bulan; gunakan titik atau tanda tanya yang sesuai; cek subject-verb; cek bentuk waktu; cek artikel a/an/the; lalu baca keras-keras untuk menemukan bagian yang terasa hilang.","Revisi tidak berarti tulisan awal buruk. Penulis yang baik membaca ulang untuk membuat pesan lebih jelas."], bullets:["Apakah setiap kalimat punya subject dan verb?","Apakah urutan idenya mudah diikuti?","Apakah kata kerja sesuai subject dan waktu?","Apakah kapital dan tanda baca sudah tepat?"]}
    ],
    mistake:{wrong:"I like English because it is useful. And my friends. And study everyday",right:"I like English because it is useful. I study it with my friends every day.",why:"Kalimat lengkap perlu subject dan verb; hindari fragmen, dan every day ditulis dua kata sebagai keterangan waktu."},
    keyPoints:["Mulai dengan satu topic sentence.","Tambahkan detail/contoh dan hubungan antarkalimat.","Baca ulang untuk mengecek grammar, kapital, dan tanda baca."],
    check:{question:"Apa fungsi topic sentence dalam paragraf?",options:["Menyatakan gagasan utama paragraf.","Mengulang semua kata sulit.","Menggantikan tanda baca."],answer:0,explanation:"Topic sentence memberi tahu pembaca ide utama yang akan dijelaskan."}
  }
];
